operations.code:
workbook.apply([
  {
    "op": "datavalidation.set",
    "target": {
      "sheet": "Validation",
      "range": "B2:B10"
    },
    "props": {
      "rule": {
        "type": "list",
        "values": [
          "Dog",
          "Cat",
          "Bat"
        ]
      },
      "prompt": {
        "title": "Pick an animal",
        "show": true
      },
      "errorAlert": {
        "title": "Invalid choice",
        "show": true
      },
      "ignoreBlanks": true,
      "inCellDropDown": true
    }
  }
]);

workbook.apply([
  {
    "op": "chart.add",
    "sheet": "Charts",
    "props": {
      "chartType": "line",
      "anchor": {
        "from": {
          "row": 1,
          "col": 1,
          "rowOffsetPx": 4,
          "colOffsetPx": 8
        },
        "extent": {
          "widthPx": 520,
          "heightPx": 280
        }
      },
      "title": "Milky Way Star Birth Rate",
      "categories": [
        "2020",
        "2021",
        "2022",
        "2023"
      ],
      "series": [
        {
          "name": "Milky Way",
          "values": [
            1.8,
            1.9,
            2,
            2.2
          ]
        }
      ],
      "hasLegend": true,
      "legend": {
        "position": "bottom"
      },
      "dataLabels": {
        "showValue": true
      }
    }
  }
]);

workbook.apply([
  {
    "op": "names.function.add",
    "name": "AddTax",
    "lambda": "LAMBDA(price, tax, price*(1+tax))",
    "description": "Adds tax to a price",
    "parameters": [
      {
        "name": "price",
        "description": "Base price"
      },
      {
        "name": "tax",
        "description": "Tax rate (e.g. 0.1)"
      }
    ],
    "returns": "Taxed price"
  }
]);

